{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#f5efe6; /* warm earth */
      --accent:#7a5a3f; /* clay */
      --muted:#8a7a6d;
      --panel:#fff8f2;
      --glass:rgba(122,90,63,0.06);
      --radius:12px;
      font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
    }
    html,body{height:100%;margin:0;background:var(--bg);color:#2b2a28}
    body{line-height:1.45}
    .site{max-width:1000px;margin:36px auto;padding:28px;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent),url('assets/img/pattern.svg');border-radius:18px;box-shadow:0 6px 30px rgba(42,38,36,0.08)}
    header{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}
    .brand{display:flex;align-items:center;gap:12px}
    .brand h1{font-size:18px;margin:0;color:var(--accent)}
    nav a{margin-left:12px;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{display:grid;grid-template-columns:1fr;gap:14px;margin-bottom:18px}
    .hero h2{margin:0;color:var(--accent)}
    .lead{background:var(--panel);padding:16px;border-radius:12px}
    .columns{display:grid;grid-template-columns:1fr 340px;gap:18px;margin-top:18px}
    .card{background:white;border-radius:12px;padding:16px;box-shadow:0 4px 18px rgba(30,30,30,0.04)}
    h3{margin-top:0;color:#3e352e}
    ul{margin:8px 0 16px 18px}
    .meta{font-size:13px;color:var(--muted)}
    footer{margin-top:22px;font-size:13px;color:var(--muted)}
    /* widgets */
    .widget{margin-top:12px;padding:14px;border-radius:12px;background:linear-gradient(180deg,var(--glass),transparent)}
    label{display:block;font-weight:600;margin-top:10px}
    input[type=text],textarea,select{width:100%;padding:8px;border-radius:8px;border:1px solid #e6ddd4;background:white}
    .row{display:flex;gap:8px}
    .btn{display:inline-block;padding:10px 14px;background:var(--accent);color:white;border-radius:8px;text-decoration:none;border:none;cursor:pointer}
    .ghost{background:transparent;border:1px solid #e0d8d2;color:var(--muted)}
    .copy-area{width:100%;height:90px;padding:10px;border-radius:8px;border:1px dashed #decfc3;background:#fffdf9;resize:vertical}
    .note{font-size:13px;color:var(--muted);margin-top:8px}
    .small{font-size:13px;color:var(--muted)}
    @media(max-width:880px){.columns{grid-template-columns:1fr;}.site{margin:18px;padding:18px}}
  </style>
</head>
<body>
  <div class="site" role="document">
    <header>
      <div class="brand">
        <div style="width:44px;height:44px;border-radius:10px;background:var(--accent);display:flex;align-items:center;justify-content:center;color:white;font-weight:700">{{BUSINESS_NAME}}</div>
        <div>
          <h1>{{BUSINESS_NAME}}</h1>
          <div class="meta">Integrative therapy — tailored, discreet, and practical</div>
        </div>
      </div>
      <nav aria-label="Primary">
        <a href="index.html">Start</a>
        <a href="about.html">About</a>
        <a href="specialties.html">Offerings</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Rates</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <section class="hero">
        <div class="lead card">
          <h2>About the practice</h2>
          <p class="small">I offer focused clinical support for individuals navigating transitions, relational shifts, and persistent patterns that feel stuck. My intention is to listen with clarity, help you name what's happening, and co-create practical steps to try between sessions.</p>
        </div>
      </section>

      <div class="columns">
        <div>
          <section class="card">
            <h3>Therapist statement</h3>
            <p>I approach therapy from an integrative, trauma-aware stance. Sessions emphasize collaboration: you'll get thoughtful clinical framing, and we will develop concrete practices and communication templates you can use outside of sessions. I aim to keep language plain and to prioritize safety, consent, and your values.</p>
            <p class="note">Confidentiality: sessions are confidential within clinical and legal limits. Scope: I provide psychotherapy and not emergency medical services. If you are in crisis or at immediate risk, please call your local emergency number or a crisis line in your area.</p>
          </section>

          <section class="card" style="margin-top:12px">
            <h3>What to expect in a first consultation</h3>
            <ul>
              <li>A brief intake to understand presenting concerns and history</li>
              <li>Collaborative goals for a short plan of work</li>
              <li>A discussion of practical steps and scheduling</li>
            </ul>
            <p class="small">If you have questions in advance, use the self-screening tool on this page to gather thoughts to bring to the consultation.</p>
          </section>

          <section class="card" style="margin-top:12px">
            <h3>Accessibility and logistics</h3>
            <p class="small">I offer in-person sessions in {{CITY}}, {{STATE}} and telehealth where appropriate. I maintain clear boundaries about record-keeping and scheduling to protect space for therapeutic work.</p>
          </section>
        </div>

        <aside>
          <div class="card">
            <h3>Quick actions</h3>
            <p class="meta">Plan a session or prepare for intake</p>
            <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>

          <div class="card" style="margin-top:12px">
            <h3>Session Planner</h3>
            <div class="widget" id="planner">
              <label for="concern">Primary focus for sessions</label>
              <input id="concern" type="text" placeholder="e.g., relationship pattern, career transition" />
              <label for="length">Preferred session length</label>
              <select id="length">
                <option>50 minutes</option>
                <option>75 minutes</option>
                <option>90 minutes</option>
              </select>
              <label for="frequency">Frequency</label>
              <select id="frequency">
                <option>Weekly</option>
                <option>Every other week</option>
                <option>Monthly</option>
              </select>
              <label for="goals">Top goals (comma separated)</label>
              <input id="goals" type="text" placeholder="e.g., reduce panic, improve boundaries" />
              <div style="margin-top:10px;display:flex;gap:8px">
                <button class="btn" id="buildPlan">Build plan</button>
                <button class="btn ghost" id="clearPlan">Clear</button>
              </div>
              <label style="margin-top:10px">Personalized plan summary</label>
              <textarea id="planOutput" class="copy-area" readonly></textarea>
              <div style="display:flex;gap:8px;margin-top:8px">
                <button class="btn" id="copyPlan">Copy summary</button>
                <button class="btn ghost" id="downloadPlan">Download</button>
              </div>
            </div>
          </div>

          <div class="card" style="margin-top:12px">
            <h3>Self-screening intake</h3>
            <div class="widget" id="wizard">
              <div id="stepArea">
                <div id="step1">
                  <label>Which areas feel most active for you right now? (select all)</label>
                  <div><label><input type="checkbox" value="Mood/Sadness" class="area"> Mood / sadness</label></div>
                  <div><label><input type="checkbox" value="Anxiety/Nervousness" class="area"> Anxiety / worry</label></div>
                  <div><label><input type="checkbox" value="Relationships" class="area"> Relationships</label></div>
                  <div><label><input type="checkbox" value="Work/Career" class="area"> Work / career</label></div>
                  <div><label><input type="checkbox" value="Sleep/Appetite" class="area"> Sleep / appetite</label></div>
                </div>

                <div id="step2" style="display:none">
                  <label>How long have these been a concern?</label>
                  <select id="duration">
                    <option>Less than 1 month</option>
                    <option>1-6 months</option>
                    <option>More than 6 months</option>
                  </select>
                  <label style="margin-top:8px">Anything that makes symptoms better or worse?</label>
                  <input id="modifiers" type="text" placeholder="e.g., more sleep helps, stress at work worsens" />
                </div>

                <div id="step3" style="display:none">
                  <label>What would you like to bring to a first session? (brief)</label>
                  <textarea id="bring" placeholder="Topics, moments, questions for therapist" style="height:72px"></textarea>
                </div>
              </div>
              <div style="display:flex;gap:8px;margin-top:10px">
                <button class="btn" id="prevStep" disabled>Back</button>
                <button class="btn" id="nextStep">Next</button>
              </div>

              <div id="wizardResult" style="display:none;margin-top:10px">
                <label>Questions to bring to your consultation</label>
                <textarea id="wizardOutput" class="copy-area" readonly></textarea>
                <div style="display:flex;gap:8px;margin-top:8px">
                  <button class="btn" id="copyWizard">Copy</button>
                </div>
              </div>
            </div>
          </div>

        </aside>
      </div>

      <footer>
        <div>Phone: {{PHONE}} &nbsp;•&nbsp; Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        <p class="note">Confidentiality and scope: notes and records are maintained in accordance with clinical practice standards. Therapy is collaborative and not a substitute for emergency or medical services. If you are in immediate danger or crisis, call your local emergency services.</p>
      </footer>
    </main>
  </div>

  <script>
    // Session Planner
    (function(){
      const concern = document.getElementById('concern');
      const length = document.getElementById('length');
      const frequency = document.getElementById('frequency');
      const goals = document.getElementById('goals');
      const build = document.getElementById('buildPlan');
      const output = document.getElementById('planOutput');
      const copyBtn = document.getElementById('copyPlan');
      const clearBtn = document.getElementById('clearPlan');
      const downloadBtn = document.getElementById('downloadPlan');

      function buildPlan(){
        const g = goals.value.trim()? goals.value.split(',').map(s=>s.trim()).filter(Boolean) : [];
        const plan = [];
        plan.push('Personalized session plan');
        plan.push('Primary focus: ' + (concern.value.trim() || 'Not specified'));
        plan.push('Session length: ' + length.value + ' • ' + frequency.value + '\n');
        if(g.length) plan.push('Top goals:\n- ' + g.join('\n- '));
        plan.push('\nWhat to bring to intake:\n- A brief timeline of when this began\n- Any patterns or triggers you notice\n- Questions about therapy approach and next steps');
        plan.push('\nContact to book: ' + '{{PHONE}}' + ' / ' + '{{EMAIL}}');
        output.value = plan.join('\n\n');
      }

      build.addEventListener('click', buildPlan);
      clearBtn.addEventListener('click', function(){concern.value='';goals.value='';output.value='';length.selectedIndex=0;frequency.selectedIndex=0});
      copyBtn.addEventListener('click', function(){navigator.clipboard.writeText(output.value).then(()=>{copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy summary',1200)})});
      downloadBtn.addEventListener('click', function(){const blob=new Blob([output.value],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='session-plan.txt';a.click();URL.revokeObjectURL(url)});
    })();

    // Intake Wizard
    (function(){
      const next = document.getElementById('nextStep');
      const prev = document.getElementById('prevStep');
      const step1 = document.getElementById('step1');
      const step2 = document.getElementById('step2');
      const step3 = document.getElementById('step3');
      const wizardResult = document.getElementById('wizardResult');
      const wizardOutput = document.getElementById('wizardOutput');
      const copyWizard = document.getElementById('copyWizard');
      let step=1;

      function show(){
        step1.style.display = step===1 ? '' : 'none';
        step2.style.display = step===2 ? '' : 'none';
        step3.style.display = step===3 ? '' : 'none';
        prev.disabled = step===1;
        next.textContent = step===3 ? 'Finish' : 'Next';
      }
      show();

      next.addEventListener('click', function(){
        if(step<3){ step++; show(); } else { buildResult(); }
      });
      prev.addEventListener('click', function(){ if(step>1){ step--; show(); } });

      function buildResult(){
        const areas = Array.from(document.querySelectorAll('.area:checked')).map(i=>i.value);
        const duration = document.getElementById('duration').value;
        const modifiers = document.getElementById('modifiers').value.trim();
        const bring = document.getElementById('bring').value.trim();

        const lines = [];
        lines.push('Notes to bring to consultation');
        if(areas.length) lines.push('\nPrimary areas: ' + areas.join(', '));
        lines.push('\nDuration: ' + duration);
        if(modifiers) lines.push('\nFactors noticed: ' + modifiers);
        if(bring) lines.push('\nTopics to raise: ' + bring);

        lines.push('\nSuggested questions for the first session:\n- How might we prioritize goals for early work?\n- Which strategies might fit my day-to-day life?\n- How will we track progress and decide when to adjust the plan?');

        wizardOutput.value = lines.join('\n\n');
        wizardResult.style.display = '';
        wizardOutput.focus();
      }

      copyWizard.addEventListener('click', function(){navigator.clipboard.writeText(wizardOutput.value).then(()=>{copyWizard.textContent='Copied'; setTimeout(()=>copyWizard.textContent='Copy',1200)})});
    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8f4ee;--accent:#6b4b3a;--muted:#7a6b63;--panel:#fff9f5;--radius:12px}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:var(--bg);color:#2e2b28}
    .wrap{max-width:980px;margin:30px auto;padding:28px;background:url('assets/img/pattern.svg'),linear-gradient(180deg,rgba(255,255,255,0.85),transparent);border-radius:16px}
    header{display:flex;justify-content:space-between;align-items:center}
    nav a{margin-left:10px;color:var(--muted);text-decoration:none;font-weight:600}
    h2{color:var(--accent)}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .panel{background:white;padding:16px;border-radius:12px;box-shadow:0 6px 18px rgba(36,30,27,0.04)}
    .service{border-left:4px solid var(--panel);padding:10px;margin-bottom:12px}
    .price{font-weight:700;color:var(--accent)}
    .muted{color:var(--muted);font-size:13px}
    .cta{margin-top:12px}
    /* small forms */
    label{display:block;margin-top:8px;font-weight:600}
    input,select,textarea{width:100%;padding:8px;border-radius:8px;border:1px solid #e9e1d8}
    .btn{background:var(--accent);color:white;padding:9px 12px;border-radius:8px;border:none;cursor:pointer}
    .copy-area{width:100%;height:84px;padding:10px;border-radius:8px;border:1px dashed #e6ded6;background:#fffdf9}
    @media(max-width:880px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div>
        <h1>{{BUSINESS_NAME}}</h1>
        <div class="muted">Offerings shaped around life and limits</div>
      </div>
      <nav>
        <a href="index.html">Start</a>
        <a href="about.html">About</a>
        <a href="specialties.html">Offerings</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Rates</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main style="margin-top:18px">
      <div class="grid">
        <section>
          <h2>Areas of focus</h2>
          <p class="muted">I work with adults in concentrated, evidence-informed cycles that emphasize clarity and usable steps. Below are common pathways clients choose to address specific life challenges.</p>

          <div class="panel" style="margin-top:12px">
            <div class="service">
              <h3>Transition Support</h3>
              <p class="muted">For people navigating big life changes (career shifts, moves, family transitions). Sessions center on decision clarity, values, and practical rhythm-building.</p>
              <div class="price">Single consult: starting at $150</div>
            </div>

            <div class="service">
              <h3>Focused Intensive</h3>
              <p class="muted">A concentrated session (extended time) to address a pressing topic with assessments and an immediate plan to try between sessions.</p>
              <div class="price">Half-day intensive: starting at $420</div>
            </div>

            <div class="service">
              <h3>Short Series</h3>
              <p class="muted">A short course of 3–6 sessions to build momentum on a particular pattern (communication, boundaries, mood regulation).</p>
              <div class="price">Short series (3 sessions): starting at $420</div>
            </div>

            <div class="service">
              <h3>Ongoing weekly work</h3>
              <p class="muted">Regular sessions for people seeking steady support and skill development over time.</p>
              <div class="price">Monthly cadence: custom, discussed in intake</div>
            </div>

            <p class="muted">Pricing is presented as a starting point and may vary with session length or complexity. There are no guarantees of outcome; therapy is collaborative and individualized.</p>
          </div>

          <section style="margin-top:14px" class="panel">
            <h3>Preparing for a focused session</h3>
            <ul>
              <li>Bring a brief timeline of the concern</li>
              <li>Note recent attempts or strategies that have and haven't worked</li>
              <li>Be ready to name small first steps you can try</li>
            </ul>
          </section>
        </section>

        <aside>
          <div class="panel">
            <h3>Planner & Intake tools</h3>
            <p class="muted">Use these interactive tools to shape a session you'd like to request and to collect questions for your first visit.</p>

            <div style="margin-top:10px">
              <label for="svcGoal">Which offering interests you?</label>
              <select id="svcGoal">
                <option>Transition Support</option>
                <option>Focused Intensive</option>
                <option>Short Series</option>
                <option>Ongoing weekly work</option>
              </select>

              <label for="note" style="margin-top:8px">Quick note for booking</label>
              <input id="note" type="text" placeholder="A line about what you'd like to work on" />

              <div style="margin-top:10px;display:flex;gap:8px">
                <button class="btn" id="makeRequest">Create request</button>
                <button class="btn" id="resetRequest" style="background:#eee;color:var(--accent);">Reset</button>
              </div>

              <label style="margin-top:8px">Request text</label>
              <textarea id="requestOut" class="copy-area" readonly></textarea>
              <div style="margin-top:8px;display:flex;gap:8px">
                <button class="btn" id="copyRequest">Copy</button>
              </div>
            </div>
          </div>

          <div class="panel" style="margin-top:12px">
            <h3>Intake mini-wizard</h3>
            <p class="muted">A quick checklist to turn into questions for your first meeting.</p>

            <div style="margin-top:8px">
              <label><input type="checkbox" id="chkSleep"> Sleep disturbance</label>
              <label><input type="checkbox" id="chkMood"> Low or changeable mood</label>
              <label><input type="checkbox" id="chkAnx"> Worry or panic</label>
              <label><input type="checkbox" id="chkRel"> Relationship strain</label>
              <label style="margin-top:8px">Additional notes</label>
              <input id="miniNotes" type="text" placeholder="Short note to clinician" />

              <div style="display:flex;gap:8px;margin-top:10px">
                <button class="btn" id="makeQuestions">Make questions</button>
                <button class="btn" id="clearQuestions" style="background:#eee;color:var(--accent);">Clear</button>
              </div>

              <label style="margin-top:8px">Questions to bring</label>
              <textarea id="questionsOut" class="copy-area" readonly></textarea>
              <div style="margin-top:8px;display:flex;gap:8px"><button class="btn" id="copyQs">Copy</button></div>
            </div>
          </div>

        </aside>
      </div>

      <p class="muted" style="margin-top:16px">Confidentiality & scope: Records are held in line with clinical standards. Therapy is not emergency care. If you are in crisis, please use emergency services or local crisis lines.</p>

      <footer style="margin-top:22px;font-size:13px;color:var(--muted)">Contact: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></footer>
    </main>
  </div>

  <script>
    // Booking request builder
    (function(){
      const svc = document.getElementById('svcGoal');
      const note = document.getElementById('note');
      const make = document.getElementById('makeRequest');
      const out = document.getElementById('requestOut');
      const copy = document.getElementById('copyRequest');
      const reset = document.getElementById('resetRequest');

      make.addEventListener('click', function(){
        const lines = [];
        lines.push('Request for ' + svc.value);
        if(note.value.trim()) lines.push('\nBrief note: ' + note.value.trim());
        lines.push('\nPreferred contact: ' + '{{EMAIL}}' + ' / ' + '{{PHONE}}');
        out.value = lines.join('\n');
      });

      copy.addEventListener('click', function(){navigator.clipboard.writeText(out.value || '').then(()=>{copy.textContent='Copied';setTimeout(()=>copy.textContent='Copy',1200)})});
      reset.addEventListener('click', function(){svc.selectedIndex=0;note.value='';out.value=''});
    })();

    // Mini intake -> questions
    (function(){
      const chkSleep = document.getElementById('chkSleep');
      const chkMood = document.getElementById('chkMood');
      const chkAnx = document.getElementById('chkAnx');
      const chkRel = document.getElementById('chkRel');
      const miniNotes = document.getElementById('miniNotes');
      const makeQs = document.getElementById('makeQuestions');
      const clearQs = document.getElementById('clearQuestions');
      const out = document.getElementById('questionsOut');
      const copy = document.getElementById('copyQs');

      makeQs.addEventListener('click', function(){
        const items = [];
        if(chkSleep.checked) items.push('How might sleep be affecting mood and energy?');
        if(chkMood.checked) items.push('What patterns have I noticed around times of low mood?');
        if(chkAnx.checked) items.push('Are there techniques that can help when I feel overwhelming anxiety?');
        if(chkRel.checked) items.push('How can I bring up difficult topics with others without escalating?');
        if(miniNotes.value.trim()) items.push('Note for clinician: ' + miniNotes.value.trim());
        if(!items.length) items.push('No items selected — bring a short timeline and a few recent examples of what you notice.');
        out.value = items.join('\n\n');
      });

      clearQs.addEventListener('click', function(){chkSleep.checked=false;chkMood.checked=false;chkAnx.checked=false;chkRel.checked=false;miniNotes.value='';out.value=''});
      copy.addEventListener('click', function(){navigator.clipboard.writeText(out.value || '').then(()=>{copy.textContent='Copied';setTimeout(()=>copy.textContent='Copy',1200)})});
    })();
  </script>
</body>
</html>"} 
